x = df["StudyHours"].values
y = df["Score"].values
b = 2.1304

def sai_so(a):
    return np.mean((y - (a * x + b)) ** 2)

def tinh_do_doc(a):
    return -2 * np.mean(x * (y - (a * x + b)))

